package main

import \(
	""fmt""
	""os""
	""strings""
	""github.com/PuerkitoBio/goquery""
\)

func main\(\) {
	doc, _ := goquery.NewDocumentFromReader\(os.Stdin\)
	content := doc.Find\(""div.prose.field--name-body, div.field--name-body""\).First\(\)
	fmt.Println\(""Found:"", content.Length\(\)\)
	if content.Length\(\) > 0 {
		html, _ := content.Html\(\)
		fmt.Println\(html[:min\(500, len\(html\)\)]\)
	}
}

func min\(a, b int\) int {
	if a < b { return a }
	return b
}
